1	/**
2	 * Common Ground — SELECTED-CANDIDATE qualification (CPU only, read-only).
3	 *
4	 * Exactly ONE candidate. No search, no fallback scan, no winner selection.
5	 * Candidate = geometry-instrument.json ranges[range=12].top3[0]:
6	 *   fixed apparatus R grounded (-34, 51.05, 20), yaw 90 (quarter turn k=1),
7	 *   S(-26,51.05,12)  E(-42,51.05,12)  C(-48,51.05,12)
8	 *   intermediate witness SHIFTED by commission to W(-34,51.05,10) (was z=11)
9	 *   Terra final witness fixed at the existing JSON pose (-44,51.05,12)
10	 *
11	 * Adds the commissioned literal STAND + BRACKET solids (entirely below
12	 * grounded+1.20, i.e. below every ray socket) and includes them, with NO
13	 * exemption, in the walk mask, the walked-segment test and every ray.
14	 *
15	 * Nothing here is shipped behaviour. Finite reference range, the opaque
16	 * backing, the stand and the bracket do not exist in the runtime. No source,
17	 * canon, validator, signature, worldgen, render, GPU, browser or server is
18	 * touched. No threshold is added or relaxed.
19	 *
20	 * Terrain / DDA / trace / socket / pose conventions inherited VERBATIM from
21	 * geometry-instrument-probe.mts (itself from geometry-arena / geometry-pass2).
22	 *
23	 * Reproduce (exact):
24	 *   cd /home/thomasphillip/Projects/vox/main
25	 *   TM=$PWD/node_modules/three
26	 *   ./node_modules/.bin/esbuild \
27	 *     ../.codex/story-runs/2026-09-06-common-ground/selected-geometry-qualification.mts \
28	 *     --bundle --platform=node --format=esm --outfile=/tmp/cg-selected.mjs \
29	 *     "--alias:three=$TM/build/three.module.js" \
30	 *     "--alias:three/examples/jsm/utils/BufferGeometryUtils.js=$TM/examples/jsm/utils/BufferGeometryUtils.js"
31	 *   node /tmp/cg-selected.mjs > \
32	 *     ../.codex/story-runs/2026-09-06-common-ground/selected-geometry-qualification.json
33	 */
34	import * as THREE from 'three';
35	import { createResolvedWorldGenerator } from '../../../main/src/utils/resolvedWorldGenerator.ts';
36	import { createStoryAnchorResolver, AUDIT_WORKER_GROUND_CLEARANCE } from '../../../main/src/story/world/storyAnchorResolver.ts';
37	import { STORY_SEED, STORY_PRIMARY_WORLD_ID, STORY_COORDINATE } from '../../../main/src/story/world/storyWorldIdentity.ts';
38	import { type AgentSurfaceTerrainQuery } from '../../../main/src/utils/agentSurfaceNavigation.ts';
39	import { groundedSurfaceRouteLength } from '../../../main/src/utils/groundedSurfaceMotion.ts';
40	import { VOXEL_SCALE, voxelCoordToWorld, PLAYER_EYE_HEIGHT, PLAYER_CAPSULE_RADIUS, PLAYER_STANDING_HEIGHT } from '../../../main/src/utils/cubeGravityConstants.ts';
41	import { buildTreeProfile } from '../../../main/src/utils/treeProfile.ts';
