43	const t0 = Date.now();
44	const PLANET_SIZE = 50;
45	const RADIUS_CELLS = Math.max(1, Math.floor(PLANET_SIZE / VOXEL_SCALE)); // 25
46	const UP = new THREE.Vector3(0, 1, 0);
47	
48	const WORKER_ROUTE_OPTIONS = {
49	  face: 'top' as const,
50	  differentFaceFallback: 'unreachable' as const,
51	  clearanceCells: 2,
52	  maxSlopeCells: 1,
53	  edgeMarginCells: 1,
54	  maxVisitedCells: 8192,
55	  waypointClearanceWorld: 1.05,
56	  allowJetpackCrossing: false
57	};
58	const MAX_JETPACK_WATER_DEPTH_CELLS = 2;
59	
60	// --- unchanged caps / thresholds (verbatim; none added, none relaxed) -------
61	const MAX_TRACE_POINTS = 128;
62	const MAX_TRACE_LENGTH = 120;
63	const SAMPLE_SPACING = 1.0;
64	const MIN_SAMPLE_SEPARATION = 0.25;
65	const MIN_EXTRA_UNITS = 12;
66	const MIN_LENGTH_RATIO = 1.25;
67	const MIN_UNSUPPORTED_SPAN = 6;
68	const BODY_RADIUS = PLAYER_CAPSULE_RADIUS;            // 0.5
69	const BODY_BODY_CLEARANCE = BODY_RADIUS * 2;          // 1.0
70	const TERRA_LATERAL_MIN = 2.0;
71	const OCCUPY_R = 1.25, OCCUPY_Y = 0.6;
72	const RELEASE_R = 1.75, RELEASE_Y = 0.9;
73	const MAX_TOPFACE_CELL = 24;
74	const RANGE = 12;                                      // nominated range, unchanged
75	const CPU_BUDGET_SECONDS = 60;
76	/** Reporting-only densification of walked segments (not a threshold). */
77	const SEGMENT_DENSE_SPACING = 0.25;
78	
79	// --- sockets, measured from current source ---------------------------------
80	const WORKER_SOCKET = 1.85;          // AuditWorker torso 1.30 + visor 0.55
81	const PLAYER_SOCKET = PLAYER_EYE_HEIGHT; // 1.35
82	const FIXED_APPARATUS_SOCKET = 1.30; // the ACTUAL fixed reference plate height
83	const WORKER_BODY_HEIGHT = 2.01;
84	const PLAYER_BODY_HEIGHT = PLAYER_STANDING_HEIGHT; // 3.6
85	
86	const APPARATUS = {
87	  socketLocal: { x: 0, y: FIXED_APPARATUS_SOCKET, z: 0 },
88	  backingCenterLocal: { x: -0.90, y: 1.30, z: 0 },
89	  backingSize: { x: 0.12, y: 2.00, z: 1.60 }
90	};
91	const BACK_LO = {
92	  x: APPARATUS.backingCenterLocal.x - APPARATUS.backingSize.x / 2,
93	  y: APPARATUS.backingCenterLocal.y - APPARATUS.backingSize.y / 2,
94	  z: APPARATUS.backingCenterLocal.z - APPARATUS.backingSize.z / 2
95	};
96	const BACK_HI = {
97	  x: APPARATUS.backingCenterLocal.x + APPARATUS.backingSize.x / 2,
98	  y: APPARATUS.backingCenterLocal.y + APPARATUS.backingSize.y / 2,
99	  z: APPARATUS.backingCenterLocal.z + APPARATUS.backingSize.z / 2
100	};
