102	// --- COMMISSIONED literal below-socket solids (local frame, R ground = 0) ---
103	// Cap: grounded + 1.20 = below the LOWEST ray socket (fixed plate at 1.30).
104	const SOLID_CAP_LOCAL_Y = 1.20;
105	// Head-support post: directly under the fixed socket column, 0.40 x 0.40.
106	const STAND_LOCAL = { lo: { x: -0.20, y: 0.00, z: -0.20 }, hi: { x: 0.20, y: SOLID_CAP_LOCAL_Y, z: 0.20 } };
107	// Bracket tie: from the backing plane (x = -0.96, the board's outer face) to
108	// inside the post; 0.40 vertical thickness, top flush with the post cap.
109	const BRACKET_LOCAL = { lo: { x: -0.96, y: 0.80, z: -0.20 }, hi: { x: -0.10, y: SOLID_CAP_LOCAL_Y, z: 0.20 } };
110	
111	const CANDIDATE = {
112	  centreCell: [-17, 25, 10] as [number, number, number],
113	  centreWorldXZ: [-34, 20] as [number, number],
114	  quarterTurns: 1,
115	  yawDegrees: 90,
116	  S: [-26, 12] as [number, number],
117	  E: [-42, 12] as [number, number],
118	  C: [-48, 12] as [number, number],
119	  W: [-34, 10] as [number, number],   // COMMISSION SHIFT (nominal was z = 11)
120	  WNominal: [-34, 11] as [number, number],
121	  terra: [-44, 12] as [number, number]
122	};
123	
124	const { generator } = createResolvedWorldGenerator({
125	  worldId: STORY_PRIMARY_WORLD_ID,
126	  seed: STORY_SEED,
127	  planetRadius: PLANET_SIZE / 2
128	});
129	const voxels = generator.getAllVoxelPositions();
130	const resolver = createStoryAnchorResolver({ generator, voxels });
131	const terrain: AgentSurfaceTerrainQuery = {
132	  isSolidVoxel: (x, y, z) => generator.shouldVoxelExist(x, y, z),
133	  isWaterVoxel: (x, y, z) => generator.isWaterVoxel(x, y, z),
134	  isHazardousVoxel: (x, y, z) => generator.generateBlockForPosition(x, y, z) === 'lava'
135	};
136	const v3 = (v: THREE.Vector3) => ({ x: +v.x.toFixed(3), y: +v.y.toFixed(3), z: +v.z.toFixed(3) });
137	const r2 = (n: number) => +n.toFixed(2);
138	const elapsed = () => (Date.now() - t0) / 1000;
139	
140	const tree = resolver.getHeroTreePose(PLANET_SIZE, STORY_SEED);
141	const pond = resolver.getPondPose(PLANET_SIZE, STORY_SEED);
142	const heroProfile = buildTreeProfile((STORY_SEED ^ 0xede9) >>> 0);
143	const TRUNK_HEIGHT = Math.max(heroProfile.trunkHeight, 7.2);
144	const TRUNK_HALF = 0.55;
145	
146	// --- terrain conventions (verbatim) ----------------------------------------
147	function shippedColumnTop(vx: number, vz: number): number | null {
148	  for (let h = RADIUS_CELLS; h >= 0; h--) {
149	    if (!terrain.isSolidVoxel(vx, h, vz)) continue;
150	    if (h < RADIUS_CELLS && terrain.isSolidVoxel(vx, h + 1, vz)) continue;
151	    return h;
152	  }
153	  return null;
154	}
155	const topCache = new Map<string, number | null>();
156	function columnTop(u: number, v: number): number | null {
157	  const k = `${u},${v}`;
158	  const hit = topCache.get(k);
159	  if (hit !== undefined) return hit;
160	  const h = shippedColumnTop(u, v);
161	  topCache.set(k, h);
162	  return h;
163	}
164	interface Cell { u: number; v: number; h: number; world: THREE.Vector3 }
165	const cellCache = new Map<string, Cell | null>();
166	function cellAt(u: number, v: number): Cell | null {
167	  const key = `${u},${v}`;
168	  const hit = cellCache.get(key);
169	  if (hit !== undefined) return hit;
170	  const h = columnTop(u, v);
171	  let out: Cell | null = null;
172	  if (h !== null
173	    && h >= Math.max(Math.abs(u), Math.abs(v)) + WORKER_ROUTE_OPTIONS.edgeMarginCells
174	    && !terrain.isHazardousVoxel!(u, h, v)) {
175	    let bodyBlocked = false;
176	    let wet = terrain.isWaterVoxel(u, h, v);
177	    const scan = MAX_JETPACK_WATER_DEPTH_CELLS + WORKER_ROUTE_OPTIONS.clearanceCells;
178	    for (let lift = 1; lift <= scan; lift++) {
179	      const y = h + lift;
180	      const insideRendered = Math.max(Math.abs(u), Math.abs(y), Math.abs(v)) <= RADIUS_CELLS;
181	      const solid = insideRendered && terrain.isSolidVoxel(u, y, v);
182	      const hazard = insideRendered && terrain.isHazardousVoxel!(u, y, v);
183	      if (terrain.isWaterVoxel(u, y, v)) wet = true;
184	      if (lift <= WORKER_ROUTE_OPTIONS.clearanceCells && (solid || hazard)) bodyBlocked = true;
185	    }
186	    if (!wet && !bodyBlocked) {
187	      out = { u, v, h, world: voxelCoordToWorld(u, h, v).addScaledVector(UP, AUDIT_WORKER_GROUND_CLEARANCE) };
188	    }
189	  }
190	  cellCache.set(key, out);
191	  return out;
192	}
193	
194	// --- line of sight (verbatim DDA + boxes) ----------------------------------
195	type Box = { lo: Record<'x' | 'y' | 'z', number>; hi: Record<'x' | 'y' | 'z', number> };
196	type NamedBox = Box & { name: string };
197	function segmentHitsBox(a: THREE.Vector3, b: THREE.Vector3, lo: Box['lo'], hi: Box['hi']): boolean {
198	  const d = { x: b.x - a.x, y: b.y - a.y, z: b.z - a.z };
199	  let tmin = 0, tmax = 1;
200	  for (const ax of ['x', 'y', 'z'] as const) {
201	    const dd = d[ax];
202	    if (Math.abs(dd) < 1e-9) { if (a[ax] < lo[ax] || a[ax] > hi[ax]) return false; continue; }
203	    let t1 = (lo[ax] - a[ax]) / dd;
204	    let t2 = (hi[ax] - a[ax]) / dd;
205	    if (t1 > t2) { const s = t1; t1 = t2; t2 = s; }
206	    tmin = Math.max(tmin, t1);
207	    tmax = Math.min(tmax, t2);
208	    if (tmin > tmax) return false;
209	  }
210	  return true;
211	}
212	function trunkBox(inflate = 0): Box {
213	  const t = tree.position;
214	  return {
215	    lo: { x: t.x - TRUNK_HALF - inflate, y: t.y - inflate, z: t.z - TRUNK_HALF - inflate },
216	    hi: { x: t.x + TRUNK_HALF + inflate, y: t.y + TRUNK_HEIGHT + inflate, z: t.z + TRUNK_HALF + inflate }
217	  };
218	}
219	function los(a: THREE.Vector3, b: THREE.Vector3, exempt: Array<[number, number, number]>, boxes: NamedBox[]) {
220	  const distance = a.distanceTo(b);
221	  const dir = b.clone().sub(a);
222	  const half = VOXEL_SCALE / 2;
223	  let cx = Math.round(a.x / VOXEL_SCALE), cy = Math.round(a.y / VOXEL_SCALE), cz = Math.round(a.z / VOXEL_SCALE);
224	  const ex = Math.round(b.x / VOXEL_SCALE), ey = Math.round(b.y / VOXEL_SCALE), ez = Math.round(b.z / VOXEL_SCALE);
225	  const step = { x: Math.sign(dir.x), y: Math.sign(dir.y), z: Math.sign(dir.z) };
226	  const tDelta = { x: 0, y: 0, z: 0 } as Record<'x' | 'y' | 'z', number>;
227	  const tMax = { x: Infinity, y: Infinity, z: Infinity } as Record<'x' | 'y' | 'z', number>;
228	  const centres = { x: cx * VOXEL_SCALE, y: cy * VOXEL_SCALE, z: cz * VOXEL_SCALE };
229	  for (const ax of ['x', 'y', 'z'] as const) {
230	    const dd = dir[ax];
231	    if (dd === 0) continue;
232	    tDelta[ax] = Math.abs(VOXEL_SCALE / dd);
233	    const boundary = centres[ax] + (dd > 0 ? half : -half);
234	    tMax[ax] = (boundary - a[ax]) / dd;
235	  }
236	  const isExempt = (x: number, y: number, z: number) => exempt.some(e => e[0] === x && e[1] === y && e[2] === z);
237	  for (let guard = 0; guard < 512; guard++) {
238	    const inside = Math.max(Math.abs(cx), Math.abs(cy), Math.abs(cz)) <= RADIUS_CELLS;
239	    if (inside && terrain.isSolidVoxel(cx, cy, cz) && !isExempt(cx, cy, cz)) {
240	      return { clear: false, blockedBy: 'terrain', distance: r2(distance) };
241	    }
242	    if (cx === ex && cy === ey && cz === ez) break;
243	    const m = tMax.x <= tMax.y ? (tMax.x <= tMax.z ? 'x' : 'z') : (tMax.y <= tMax.z ? 'y' : 'z');
244	    if (tMax[m] > 1) break;
245	    if (m === 'x') cx += step.x; else if (m === 'y') cy += step.y; else cz += step.z;
246	    tMax[m] += tDelta[m];
247	  }
248	  const tb = trunkBox();
249	  if (segmentHitsBox(a, b, tb.lo, tb.hi)) return { clear: false, blockedBy: 'trunk', distance: r2(distance) };
250	  for (const bx of boxes) {
251	    if (segmentHitsBox(a, b, bx.lo, bx.hi)) return { clear: false, blockedBy: bx.name, distance: r2(distance) };
252	  }
253	  return { clear: true, blockedBy: null as string | null, distance: r2(distance) };
254	}
255	function exemptAt(p: THREE.Vector3): Array<[number, number, number]> {
256	  const su = Math.round(p.x / VOXEL_SCALE), sv = Math.round(p.z / VOXEL_SCALE);
257	  const sh = columnTop(su, sv);
258	  return sh === null ? [] : [[su, sh, sv], [su, sh + 1, sv]];
259	}
260	interface Support { distance: number; inRange: boolean; clear: boolean; blockedBy: string | null; supported: boolean }
261	function supportPoint(actorGround: THREE.Vector3, actorH: number, refSocket: THREE.Vector3,
262	  refGround: THREE.Vector3, range: number, boxes: NamedBox[]): Support {
263	  const a = actorGround.clone().addScaledVector(UP, actorH);
264	  const distance = a.distanceTo(refSocket);
265	  if (distance > range) return { distance: r2(distance), inRange: false, clear: false, blockedBy: 'out-of-range', supported: false };
266	  const l = los(a, refSocket, [...exemptAt(actorGround), ...exemptAt(refGround)], boxes);
267	  return { distance: r2(distance), inRange: true, clear: l.clear, blockedBy: l.blockedBy, supported: l.clear };
268	}
269	
270	// --- trace sampling (verbatim, undecimated) --------------------------------
271	function traceSamples(points: THREE.Vector3[]): THREE.Vector3[] {
272	  const out: THREE.Vector3[] = [];
273	  if (!points.length) return out;
274	  out.push(points[0].clone());
275	  let last = points[0].clone();
276	  let lastHeading: THREE.Vector3 | null = null;
277	  for (let i = 1; i < points.length; i++) {
278	    const a = points[i - 1];
279	    const b = points[i];
280	    const segLen = a.distanceTo(b);
281	    if (segLen < 1e-9) continue;
282	    const heading = b.clone().sub(a).setY(0).normalize();
283	    const turned = lastHeading ? heading.dot(lastHeading) < Math.cos(Math.PI / 12) : false;
284	    let travelled = 0;
285	    while (travelled < segLen) {
286	      const need = turned && last.distanceTo(a) >= MIN_SAMPLE_SEPARATION ? MIN_SAMPLE_SEPARATION : SAMPLE_SPACING;
287	      const remaining = need - last.distanceTo(a.clone().lerp(b, travelled / segLen));
288	      travelled += Math.max(0.05, remaining);
289	      if (travelled > segLen) break;
290	      const p = a.clone().lerp(b, travelled / segLen);
291	      if (p.distanceTo(last) >= MIN_SAMPLE_SEPARATION) { out.push(p); last = p.clone(); }
292	    }
293	    lastHeading = heading;
294	  }
295	  const end = points[points.length - 1];
296	  if (end.distanceTo(last) > 1e-3) out.push(end.clone());
297	  return out;
298	}
299	/** Reporting-only: dense points covering the whole walked polyline (segments). */
300	function densePoints(points: THREE.Vector3[]): THREE.Vector3[] {
301	  const out: THREE.Vector3[] = [points[0].clone()];
302	  for (let i = 1; i < points.length; i++) {
303	    const a = points[i - 1], b = points[i];
304	    const len = a.distanceTo(b);
305	    const n = Math.max(1, Math.ceil(len / SEGMENT_DENSE_SPACING));
306	    for (let s = 1; s <= n; s++) out.push(a.clone().lerp(b, s / n));
307	  }
308	  return out;
309	}
310	
311	// --- node field (verbatim) -------------------------------------------------
312	const nodes: Cell[] = [];
313	const nodeIndex = new Map<string, number>();
314	for (let u = -MAX_TOPFACE_CELL; u <= MAX_TOPFACE_CELL; u++) {
315	  for (let v = -MAX_TOPFACE_CELL; v <= MAX_TOPFACE_CELL; v++) {
316	    const c = cellAt(u, v);
317	    if (!c) continue;
318	    nodeIndex.set(`${u},${v}`, nodes.length);
319	    nodes.push(c);
320	  }
321	}
322	const NEIGHBORS: Array<[number, number]> = [[1, 0], [-1, 0], [0, 1], [0, -1]];
323	const adjacency: number[][] = nodes.map((c) => {
324	  const out: number[] = [];
325	  for (const [du, dv] of NEIGHBORS) {
326	    const j = nodeIndex.get(`${c.u + du},${c.v + dv}`);
327	    if (j === undefined) continue;
328	    if (Math.abs(nodes[j].h - c.h) > WORKER_ROUTE_OPTIONS.maxSlopeCells) continue;
329	    out.push(j);
330	  }
331	  return out;
332	});
333	const trunkAllowed = new Uint8Array(nodes.length).fill(1);
334	{
335	  const box = trunkBox(BODY_RADIUS);
336	  for (let i = 0; i < nodes.length; i++) {
337	    const c = nodes[i];
338	    if (c.world.x >= box.lo.x && c.world.x <= box.hi.x && c.world.z >= box.lo.z && c.world.z <= box.hi.z) trunkAllowed[i] = 0;
339	  }
340	}
341	function bfsPath(fromIdx: number, toIdx: number, allowed: Uint8Array): number[] | null {
342	  if (!allowed[fromIdx] || !allowed[toIdx]) return null;
343	  const prev = new Int32Array(nodes.length).fill(-1);
344	  const seen = new Uint8Array(nodes.length);
345	  const queue = [fromIdx];
346	  seen[fromIdx] = 1;
347	  for (let qi = 0; qi < queue.length; qi++) {
348	    const cur = queue[qi];
349	    if (cur === toIdx) {
350	      const path: number[] = [];
351	      for (let n = cur; n !== -1; n = prev[n]) path.push(n);
352	      return path.reverse();
353	    }
354	    for (const nx of adjacency[cur]) {
355	      if (seen[nx] || !allowed[nx]) continue;
356	      seen[nx] = 1; prev[nx] = cur; queue.push(nx);
357	    }
358	  }
359	  return null;
360	}
361	function leastSupportedShortestPath(fromIdx: number, toIdx: number, allowed: Uint8Array, cov: Uint8Array): number[] | null {
362	  if (!allowed[fromIdx] || !allowed[toIdx]) return null;
363	  const dist = new Int32Array(nodes.length).fill(-1);
364	  dist[fromIdx] = 0;
365	  const order: number[] = [fromIdx];
366	  for (let qi = 0; qi < order.length; qi++) {
367	    for (const nx of adjacency[order[qi]]) {
368	      if (dist[nx] !== -1 || !allowed[nx]) continue;
369	      dist[nx] = dist[order[qi]] + 1; order.push(nx);
370	    }
371	  }
372	  if (dist[toIdx] === -1) return null;
373	  const dp = new Int32Array(nodes.length).fill(0x7fffffff);
374	  const from = new Int32Array(nodes.length).fill(-1);
375	  dp[fromIdx] = cov[fromIdx] ? 1 : 0;
376	  for (const n of order) {
377	    if (n === fromIdx || dist[n] > dist[toIdx]) continue;
378	    let bestCost = 0x7fffffff, bestPrev = -1;
379	    for (const p of adjacency[n]) {
380	      if (!allowed[p] || dist[p] !== dist[n] - 1 || dp[p] === 0x7fffffff) continue;
381	      const c = dp[p] + (cov[n] ? 1 : 0);
382	      if (c < bestCost || (c === bestCost && bestPrev !== -1 && (nodes[p].u < nodes[bestPrev].u
383	        || (nodes[p].u === nodes[bestPrev].u && nodes[p].v < nodes[bestPrev].v)))) { bestCost = c; bestPrev = p; }
384	    }
385	    if (bestPrev !== -1) { dp[n] = bestCost; from[n] = bestPrev; }
386	  }
387	  if (dp[toIdx] === 0x7fffffff) return null;
388	  const path: number[] = [];
389	  for (let n = toIdx; n !== -1; n = from[n]) path.push(n);
390	  return path.reverse();
391	}
392	function distanceToPolyline(p: THREE.Vector3, pts: THREE.Vector3[]): number {
393	  let best = Infinity;
394	  const ab = new THREE.Vector3(), ap = new THREE.Vector3();
395	  for (let i = 1; i < pts.length; i++) {
396	    const a = pts[i - 1], b = pts[i];
397	    ab.subVectors(b, a); ap.subVectors(p, a);
398	    const denom = ab.lengthSq();
399	    const t = denom < 1e-9 ? 0 : Math.max(0, Math.min(1, ap.dot(ab) / denom));
400	    best = Math.min(best, p.distanceTo(a.clone().addScaledVector(ab, t)));
401	  }
