725	note(terraReport.everyDensePointInRange && terraReport.everyDensePointUnobstructed, 'a worker final-traversal dense segment point is out of range or obstructed from Terra');
726	note(terraReport.meetsLateralMin && terraReport.meetsBodyBodyClearance && !terraReport.standsAtC, 'Terra witness violates lateral/body clearance');
727	
728	// --- solid-vs-body / solid-vs-path / solid-vs-ray intersection audit -------
729	const bodyKeys = ['S', 'E', 'C', 'W', 'T'] as const;
730	const bodyIntersections = bodyKeys.map(key => {
731	  const p = poses[key]!;
732	  const per = SOLIDS.map(b => {
733	    const dx = Math.max(b.lo.x - p.world.x, 0, p.world.x - b.hi.x);
734	    const dz = Math.max(b.lo.z - p.world.z, 0, p.world.z - b.hi.z);
735	    const planar = Math.hypot(dx, dz);
736	    const bodyTop = p.world.y + (key === 'W' || key === 'T' ? PLAYER_BODY_HEIGHT : WORKER_BODY_HEIGHT);
737	    const vertOverlap = Math.min(bodyTop, b.hi.y) - Math.max(p.world.y, b.lo.y) > 0;
738	    return { solid: b.name, planarGapToSurface: r2(planar), capsuleIntersects: planar < BODY_RADIUS && vertOverlap };
739	  });
740	  return { body: key, position: v3(p.world), perSolid: per, anyIntersection: per.some(x => x.capsuleIntersects) };
741	});
742	note(!bodyIntersections.some(b => b.anyIntersection), 'a body capsule intersects a literal solid');
743	
744	const pathIntersections = [
745	  { path: 'short S->E', hit: segBlocked(shortM.pts) },
746	  { path: 'long S->E', hit: segBlocked(longM.pts) },
747	  { path: 'common E->C', hit: segBlocked(ecM.pts) }
748	];
749	note(!pathIntersections.some(p => p.hit), 'a walked path intersects a literal solid or the trunk');
750	
751	// Every ray actually cast in this qualification, classified per solid.
752	type RaySet = { name: string; rays: Array<[THREE.Vector3, THREE.Vector3]> };
753	const raySets: RaySet[] = [
754	  { name: 'short-route samples -> fixed 1.30 socket', rays: shortM.samples.map(p => [p.clone().addScaledVector(UP, WORKER_SOCKET), refSocket] as [THREE.Vector3, THREE.Vector3]) },
755	  { name: 'long-route dense -> fixed 1.30 socket', rays: longM.dense.map(p => [p.clone().addScaledVector(UP, WORKER_SOCKET), refSocket] as [THREE.Vector3, THREE.Vector3]) },
756	  { name: 'E->C dense -> held worker socket at E (1.85)', rays: ecM.dense.map(p => [p.clone().addScaledVector(UP, PLAYER_SOCKET), heldE] as [THREE.Vector3, THREE.Vector3]) },
757	  { name: 'worker final dense -> Terra socket (1.35)', rays: workerFinal.dense.map(p => [p.clone().addScaledVector(UP, WORKER_SOCKET), terraSocket] as [THREE.Vector3, THREE.Vector3]) },
758	  { name: 'unsupported-span samples -> shifted W socket (1.35)', rays: spanPoints.map(p => [p.clone().addScaledVector(UP, WORKER_SOCKET), new THREE.Vector3(poses.W!.world.x, poses.W!.world.y + PLAYER_SOCKET, poses.W!.world.z)] as [THREE.Vector3, THREE.Vector3]) }
759	];
760	const rayAudit = raySets.map(rs => {
761	  const counts: Record<string, number> = { backing: 0, stand: 0, bracket: 0 };
762	  let minY = Infinity;
763	  for (const [a, b] of rs.rays) {
764	    minY = Math.min(minY, a.y, b.y);
765	    for (const s of SOLIDS) if (segmentHitsBox(a, b, s.lo, s.hi)) counts[s.name]++;
766	  }
767	  return { raySet: rs.name, rayCount: rs.rays.length, minRayEndpointY: r2(minY),
768	    minRayEndpointAboveSolidCap: minY > solidCapY, hitsPerSolid: counts };
769	});
770	note(rayAudit.every(r => r.hitsPerSolid.stand === 0 && r.hitsPerSolid.bracket === 0),
771	  'a ray intersects the stand or the bracket (below-socket solids should be geometrically unreachable by socket-to-socket rays)');
772	note(rayAudit.every(r => r.minRayEndpointAboveSolidCap), 'a ray endpoint sits at or below the solid cap');
