774	// --- socket metadata disambiguation ---------------------------------------
775	const genericPoseRSocketY = Rp.world.y + WORKER_SOCKET;
776	const socketDisambiguation = {
777	  actualFixedReferenceSocketHeight: FIXED_APPARATUS_SOCKET,
778	  actualFixedReferenceSocketWorld: v3(refSocket),
779	  usedByEveryFixedReferencePredicate: true,
780	  genericPosesRSocketHeightInBroadJson: WORKER_SOCKET,
781	  genericPosesRSocketWorldInBroadJson: v3(new THREE.Vector3(Rp.world.x, genericPoseRSocketY, Rp.world.z)),
782	  genericPosesREntryIsMetadataOnly: 'geometry-instrument-probe.mts emits poses.* with the worker socket 1.85 for every key except W; the R entry therefore reports 1.85 as generic per-pose metadata. No predicate reads it — apparatus.socketWorld (1.30) is the fixed reference.',
783	  verticalDifferenceUnits: r2(genericPoseRSocketY - refSocket.y),
784	  counterfactualIfGenericSocketWereUsed: (() => {
785	    const wrong = new THREE.Vector3(Rp.world.x, genericPoseRSocketY, Rp.world.z);
786	    const sSw = supportPoint(poses.S!.world, WORKER_SOCKET, wrong, Rp.world, RANGE, SOLIDS);
787	    const covWrong = shortM.samples.map(p => supportPoint(p, WORKER_SOCKET, wrong, Rp.world, RANGE, SOLIDS));
788	    const runWrong = longestFalseRun(shortM.samples, covWrong.map(s => s.supported));
789	    return { S_distance: sSw.distance, S_supported: sSw.supported, unsupportedShortSpanUnits: r2(runWrong.walked),
790	      differsFromMeasured: Math.abs(runWrong.walked - run.walked) > 1e-9 || sSw.distance !== sS.distance };
791	  })()
792	};
793	
794	// --- head connection caveat ------------------------------------------------
795	const headConnection = {
796	  fixedSocketWorldY: r2(refSocket.y),
797	  solidCapWorldY: r2(solidCapY),
798	  standTopWorldY: r2(stand.hi.y),
799	  standTopDirectlyUnderSocketColumn: refSocket.x >= stand.lo.x && refSocket.x <= stand.hi.x && refSocket.z >= stand.lo.z && refSocket.z <= stand.hi.z,
800	  verticalGapStandTopToSocketUnits: r2(refSocket.y - stand.hi.y),
801	  caveat: 'The commissioned cap (grounded+1.20) is 0.10 BELOW the fixed reference plate at grounded+1.30, so no literal solid can touch the socket point itself. The stand post terminates directly beneath the socket column with a 0.10 vertical gap; the plate/head above the cap is NOT modelled as a solid here. Reported, not fabricated.',
802	  bracketTouchesBacking: overlapVolume(bracket, backing),
803	  bracketTouchesStand: overlapVolume(bracket, stand),
804	  backingBottomAboveGroundUnits: r2(backing.lo.y - Rp.world.y)
805	};
806	
807	const out = {
808	  probe: 'common-ground SELECTED-CANDIDATE qualification (exactly one candidate, no search)',
809	  generatedAt: new Date().toISOString(),
810	  status: 'PREPRODUCTION MEASUREMENT — proposed apparatus, proposed finite range, proposed stand/bracket collision solids; not shipped behaviour',
811	  selectsWinner: false,
812	  ownGeometryProposed: false,
813	  scope: 'bounded collision layout specification for the already nominated passive apparatus; no new story proposal',
814	  candidateSource: 'geometry-instrument.json ranges[range=12].top3[0]',
815	  candidate: CANDIDATE,
816	  conventionsInheritedFrom: 'geometry-instrument-probe.mts (rendered-cube gate + Amanatides-Woo DDA + measured sockets + trunk collider + undecimated 1.0/0.25 sampling)',
817	  world: {
818	    planetSize: PLANET_SIZE, radiusCells: RADIUS_CELLS, storyCoordinate: STORY_COORDINATE,
819	    storySeed: STORY_SEED, worldId: STORY_PRIMARY_WORLD_ID, voxelScale: VOXEL_SCALE, voxelCount: voxels.length,
820	    heroTree: v3(tree.position), pondSearchOrigin: pond ? v3(pond.surface) : null,
821	    dryWalkableNodesOnBoundedTopFace: nodes.length
822	  },
823	  thresholds: {
824	    range: RANGE, minExtraUnits: MIN_EXTRA_UNITS, minLengthRatio: MIN_LENGTH_RATIO,
825	    minUnsupportedShortSpanUnits: MIN_UNSUPPORTED_SPAN, bodyBodyClearance: BODY_BODY_CLEARANCE,
826	    terraLateralMinUnits: TERRA_LATERAL_MIN, maxTracePoints: MAX_TRACE_POINTS, maxTraceLength: MAX_TRACE_LENGTH,
827	    sampleSpacing: SAMPLE_SPACING, cornerSpacing: MIN_SAMPLE_SEPARATION,
828	    occupancyCylinder: { radius: OCCUPY_R, vertical: OCCUPY_Y }, releaseCylinder: { radius: RELEASE_R, vertical: RELEASE_Y },
829	    newThresholdsAdded: 'none', relaxationsApplied: 'none',
830	    denseSegmentSpacingIsReportingOnly: SEGMENT_DENSE_SPACING
831	  },
832	  sockets: {
833	    fixedApparatusPlate: FIXED_APPARATUS_SOCKET, workerVisor: WORKER_SOCKET, playerEye: PLAYER_SOCKET,
834	    workerBodyHeight: WORKER_BODY_HEIGHT, playerBodyHeight: PLAYER_BODY_HEIGHT, bodyRadius: BODY_RADIUS
835	  },
836	  socketDisambiguation,
837	  grounding,
838	  solids: {
839	    localFrame: { backing: { lo: BACK_LO, hi: BACK_HI }, stand: STAND_LOCAL, bracket: BRACKET_LOCAL, capLocalY: SOLID_CAP_LOCAL_Y },
840	    world: SOLIDS.map(boxReport),
841	    solidCapWorldY: r2(solidCapY),
842	    standAndBracketEntirelyBelowCap: stand.hi.y <= solidCapY + 1e-9 && bracket.hi.y <= solidCapY + 1e-9,
843	    capBelowEveryRaySocket: {
844	      fixedPlate: r2(refSocket.y), workerVisorAtE: r2(heldE.y), playerEyeAtW: r2(poses.W!.world.y + PLAYER_SOCKET),
845	      playerEyeAtTerra: r2(terraSocket.y), capBelowAll: solidCapY < Math.min(refSocket.y, heldE.y, terraSocket.y)
846	    },
847	    exemptions: 'none — backing, stand and bracket are all in the walk mask, the walked-segment test and every ray',
848	    footprintColumns: footingColumns.length, footprintColumnsUniformHeight: footing
849	  },
850	  headConnection,
851	  fixedValidEndpoints: {
852	    S: { distance: sS.distance, rangeMargin: r2(RANGE - sS.distance), supported: sS.supported, blockedBy: sS.blockedBy },
853	    E: { distance: sE.distance, rangeMargin: r2(RANGE - sE.distance), supported: sE.supported, blockedBy: sE.blockedBy }
854	  },
855	  surveyRouteShort: {
856	    ...shortCaps, vertices: shortM.pts.map(v3),
857	    unsupportedSpanUnits: r2(run.walked), unsupportedSpanSamples: spanPoints.length,
858	    spanStart: v3(spanPoints[0]), spanEnd: v3(spanPoints[spanPoints.length - 1]),
859	    spanBlockReasons: spanReasons, spanCausedSolelyByBacking: spanReasons.length === 1 && spanReasons[0] === 'backing'
860	  },
861	  surveyRouteLong: { ...longCaps, vertices: longM.pts.map(v3) },
862	  endpointReferenceInsufficiency: { S: endpointS, E: endpointE, neitherEndpointCoversWholeSpan: !endpointS.covers && !endpointE.covers },
863	  intermediateWitness: { shifted: wShift, nominalForComparison: wNominal },
864	  commonComparisonEtoC: {
865	    ...ecReport,
866	    reciprocalNecessity: commonRun ? {
867	      contiguousSpanUnits: r2(commonRun.walked),
868	      spanStart: v3(ecM.samples[commonRun.s]), spanEnd: v3(ecM.samples[commonRun.e]),
869	      fractionOfPassage: +(commonRun.walked / ecM.length).toFixed(3), nonzero: commonRun.walked > 0
870	    } : { contiguousSpanUnits: 0, nonzero: false }
871	  },
872	  terraFinalWitness: terraReport,
873	  intersectionAudit: { bodies: bodyIntersections, paths: pathIntersections, rays: rayAudit },
874	  routeIdentityVsBroadProbe: {
875	    shortWalkedUnits: r2(shortM.length), broadShortWalkedUnits: 16,
876	    longWalkedUnits: r2(longM.length), broadLongWalkedUnits: 32,
877	    commonWalkedUnits: r2(ecM.length), broadCommonWalkedUnits: 18,
878	    sameShortLongCommonRoutes: r2(shortM.length) === 16 && r2(longM.length) === 32 && r2(ecM.length) === 18
879	  },
